create table if not exists public.task (
  id text primary key,
  created_date timestamptz not null default now(),
  updated_date timestamptz not null default now(),
  created_by text,
  created_by_id text,
  "task_ref" text not null,
  "project_id" text not null,
  "phase_id" text,
  "location_id" text,
  "floor_id" text,
  "area_ids" jsonb,
  "area_label" text,
  "scope_type" text,
  "source_location_text" text,
  "scope_unresolved" boolean default false,
  "acceptance_criterion" text,
  "discipline" text not null,
  "work_package" text,
  "parent_task_id" text,
  "is_villa_work_parent" boolean default false,
  "villa_work_key" text,
  "child_villa_count" numeric,
  "name" text not null,
  "description" text,
  "priority" text default 'Medium',
  "status" text default 'Not Started',
  "contractor_id" text,
  "assignee_user_id" text,
  "watcher_ids" jsonb,
  "responsible_engineer" text,
  "progress_percent" numeric,
  "planned_quantity" numeric,
  "completed_quantity" numeric,
  "measurement_unit" text,
  "baseline_start" date,
  "baseline_finish" date,
  "baseline_approval_status" text default 'Not Submitted',
  "baseline_version_id" text,
  "baseline_locked" boolean default false,
  "current_forecast_finish" date,
  "actual_start" date,
  "actual_finish" date,
  "date_revision_reason" text,
  "date_revision_category" text,
  "planned_manpower" numeric,
  "actual_manpower" numeric,
  "estimated_manhours" numeric,
  "actual_manhours" numeric,
  "supplied_by" text,
  "selection_status" text default 'Not Required',
  "procurement_status" text default 'Not Required',
  "expected_delivery_date" date,
  "owner_access_required" text default 'No',
  "rejection_count" numeric default 0,
  "rework_pending" boolean default false,
  "last_rejection_category" text,
  "last_rejection_reason" text,
  "owner_ack_name" text,
  "owner_ack_date" date,
  "owner_ack_method" text,
  "owner_ack_evidence_uri" text,
  "owner_ack_by_name" text,
  "access_status" text default 'Not Required',
  "blocker_category" text,
  "blocker_description" text,
  "blocker_responsible_party" text,
  "blocked_since" date,
  "remarks" text,
  "latest_update" text,
  "latest_report_date" date,
  "attachment_ref" text,
  "source_reference" text,
  "import_batch_id" text,
  "import_source_file" text,
  "import_source_sheet" text,
  "import_row_number" numeric,
  "source_status" text,
  "needs_completion_verification" boolean default false,
  "completion_verified_by_id" text,
  "completion_verified_by_name" text,
  "completion_verified_at" timestamptz,
  "execution_completed_by_id" text,
  "execution_completed_by_name" text,
  "approved_by_id" text,
  "approved_by_name" text,
  "approved_at" timestamptz,
  "created_by_name" text,
  "updated_by_name" text,
  "archived" boolean default false,
  "is_demo" boolean default false,
  "member_ids" jsonb,
  constraint task_scope_type_check check ("scope_type" is null or "scope_type" in ('Specific Room/Area', 'Multiple Rooms/Areas', 'Entire Floor', 'Entire Villa', 'Site-wide')),
  constraint task_priority_check check ("priority" is null or "priority" in ('Low', 'Medium', 'High', 'Critical')),
  constraint task_status_check check ("status" is null or "status" in ('Not Started', 'In Progress', 'Blocked', 'Execution Complete', 'Under Inspection', 'Approved', 'Closed')),
  constraint task_baseline_approval_status_check check ("baseline_approval_status" is null or "baseline_approval_status" in ('Not Submitted', 'Submitted', 'Approved', 'Rejected')),
  constraint task_date_revision_category_check check ("date_revision_category" is null or "date_revision_category" in ('Drawing/Design', 'Material', 'Labour', 'Predecessor', 'Client decision', 'Weather', 'Access', 'Rework', 'Other')),
  constraint task_supplied_by_check check ("supplied_by" is null or "supplied_by" in ('DVG', 'Contractor', 'Client')),
  constraint task_selection_status_check check ("selection_status" is null or "selection_status" in ('Not Required', 'Pending Selection', 'Selected')),
  constraint task_procurement_status_check check ("procurement_status" is null or "procurement_status" in ('Not Required', 'To Order', 'Ordered', 'Delivered', 'Installed')),
  constraint task_owner_access_required_check check ("owner_access_required" is null or "owner_access_required" in ('Yes', 'No')),
  constraint task_last_rejection_category_check check ("last_rejection_category" is null or "last_rejection_category" in ('Workmanship', 'Incomplete', 'Wrong material', 'Not to drawing', 'Other')),
  constraint task_owner_ack_method_check check ("owner_ack_method" is null or "owner_ack_method" in ('Signed sheet (photo)', 'WhatsApp confirmation (screenshot)', 'Told to the engineer')),
  constraint task_access_status_check check ("access_status" is null or "access_status" in ('Not Required', 'Pending', 'Confirmed', 'Denied')),
  constraint task_blocker_category_check check ("blocker_category" is null or "blocker_category" in ('Previous Work Incomplete', 'Materials Pending', 'Client Selection Pending', 'Owner Access Pending', 'Drawing / Design Clarification', 'Contractor Manpower', 'DVG Approval', 'External Utility / Authority', 'Other'))
);
